            <ul className="mt-3 list-inside list-disc break-words text-xs leading-6">{config.missing_settings.map((name) => <li key={name}><code>{name}</code></li>)}</ul>
          </div>
        ) : null}
        {!loading && !projects.length && !error ? (
          <form className="space-y-3 rounded-xl border p-4" onSubmit={async (event) => {
            event.preventDefault(); setCreatingProject(true); setSubmitError("");
            try {
              const project = await api<Project>("/projects", { method: "POST", body: JSON.stringify({ name: projectName.trim() }) });
              setProjects([project]); setProjectId(project.id); setProjectName("");
            } catch (error) { setSubmitError(message(error)); }
            finally { setCreatingProject(false); }
          }}>
            <p className="text-sm font-medium">Create a project to organize your research</p>
            <label htmlFor="project-name" className="sr-only">Project name</label>
            <input id="project-name" className={inputClass} placeholder="Project name" required maxLength={100} value={projectName} onChange={(event) => setProjectName(event.target.value)} disabled={creatingProject} />
            <Button type="submit" disabled={creatingProject}><Plus aria-hidden="true" />{creatingProject ? "Creating…" : "Create project"}</Button>
          </form>
        ) : null}
        <form onSubmit={submit} className="space-y-5" aria-busy={submitting}>
          <div className="space-y-2">
            <label htmlFor="project" className="text-sm font-medium">Project</label>
            <select id="project" required className={inputClass} value={projectId} onChange={(event) => setProjectId(event.target.value)} disabled={loading || submitting || !projects.length}>
              {!projects.length ? <option value="">No projects available</option> : null}
              {projects.map((project) => <option key={project.id} value={project.id}>{project.name}</option>)}
            </select>
          </div>
          <div className="space-y-2">
            <label htmlFor="goal" className="text-sm font-medium">Research question</label>
            <textarea id="goal" className={`${inputClass} min-h-44 resize-y leading-relaxed`} placeholder="Describe the question, the evidence you need, and what a useful answer should include." minLength={20} maxLength={8000} required value={goal} onChange={(event) => setGoal(event.target.value)} disabled={submitting || loading} aria-describedby="goal-help" />
            <p id="goal-help" className="text-xs text-muted-foreground">20–8,000 characters. Be specific about the desired outcome.</p>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2"><label htmlFor="cost" className="text-sm font-medium">Maximum cost (USD)</label><input id="cost" className={`${inputClass} tabular-nums`} type="number" min="0.0001" max="5" step="0.0001" required value={cost} onChange={(event) => setCost(event.target.value)} disabled={submitting} aria-describedby="cost-help" /><p id="cost-help" className="text-xs text-muted-foreground">Up to $5 per task</p></div>
            <div className="space-y-2"><label htmlFor="seconds" className="text-sm font-medium">Time limit (seconds)</label><input id="seconds" className={`${inputClass} tabular-nums`} type="number" min="30" max="1200" step="1" required value={seconds} onChange={(event) => setSeconds(event.target.value)} disabled={submitting} aria-describedby="time-help" /><p id="time-help" className="text-xs text-muted-foreground">30–1,200 seconds</p></div>
          </div>
          <details className="text-sm">
            <summary className="cursor-pointer font-medium outline-none focus-visible:ring-2 focus-visible:ring-ring">Allow webpage retrieval</summary>
            <div className="mt-3 space-y-2"><label htmlFor="hosts" className="text-sm">Allowed public domains</label><input id="hosts" className={inputClass} value={hosts} onChange={(event) => setHosts(event.target.value)} disabled={submitting} placeholder="docs.example.com, example.org" aria-describedby="hosts-help" /><p id="hosts-help" className="text-xs leading-relaxed text-muted-foreground">Optional. Up to 20 exact domains, separated by commas. With no domains, agents can search but cannot fetch pages. Subdomains need their own entry.</p></div>
          </details>
          {submitError ? <p role="alert" className="text-sm text-destructive">{submitError}</p> : null}
          {createdTask ? <div role="status" className="rounded-xl border bg-muted/30 p-4 text-sm"><p>Research task created.</p><Link href={`/tasks/${createdTask.id}`} className="mt-2 inline-flex items-center gap-2 font-medium underline underline-offset-4">Open task<ArrowRight aria-hidden="true" className="size-4" /></Link></div> : null}
          <Button type="submit" size="lg" disabled={submitting || loading || !projectId || !config?.research_configured}>{submitting ? "Creating task…" : "Start research"}<ArrowRight aria-hidden="true" /></Button>
          <p className="max-w-prose text-xs leading-relaxed text-muted-foreground">Task creation queues work for the separate worker. Configuration presence does not confirm that a worker or provider is available.</p>
        </form>
      </section>

      <section aria-labelledby="recent-title" className="min-w-0 border-t pt-7 lg:border-t-0 lg:pt-0">
        <div className="mb-5 flex items-center justify-between gap-3"><h2 id="recent-title" className="text-lg font-semibold">Recent tasks</h2><Button variant="ghost" size="sm" onClick={() => setRefresh((value) => value + 1)} disabled={loading}><RefreshCw aria-hidden="true" />Refresh</Button></div>
        {loading ? <div aria-label="Loading tasks" className="space-y-3">{[0, 1, 2].map((item) => <div key={item} className="h-20 rounded-lg bg-muted" />)}</div> : !tasks.length ? <div className="border-y py-10"><p className="text-sm font-medium">{offset ? "No more tasks" : "Your research starts here"}</p><p className="mt-2 text-sm leading-relaxed text-muted-foreground">{offset ? "Return to the previous page to see earlier results." : "Create a task to see its plan, agent runs, and evidence in this workspace."}</p></div> : <ul className="divide-y border-y">{tasks.map((task) => <li key={task.id}><Link href={`/tasks/${task.id}`} className="block space-y-2 py-5 outline-none hover:bg-muted/30 focus-visible:ring-2 focus-visible:ring-ring"><div className="flex flex-wrap items-center justify-between gap-2"><Badge variant={task.status === "FAILED" ? "destructive" : "secondary"}>{statusLabel(task.status)}</Badge><time dateTime={task.created_at} className="text-xs text-muted-foreground">{formatDate(task.created_at)}</time></div><p className="line-clamp-2 text-sm font-medium leading-relaxed">{task.goal}</p><p className="text-xs text-muted-foreground">{projects.find((project) => project.id === task.project_id)?.name ?? "Project"} · ${task.max_cost_usd} limit</p></Link></li>)}</ul>}
