      if (!scoped.length) return;
      cursor = Math.max(cursor, ...scoped.map((event) => event.sequence));
      setEvents((current) => [...new Map([...current, ...scoped].map((event) => [event.sequence, event])).values()]
        .sort((a, b) => a.sequence - b.sequence).slice(-200));
    }

